CREATE TABLE IF NOT EXISTS "comment_lens_scan" ("id" text PRIMARY KEY NOT NULL, "owner" text NOT NULL, "repository" text NOT NULL, "ref" text NOT NULL, "status" text NOT NULL, "head_commit" text, "comment_count" integer DEFAULT 0 NOT NULL, "diagnostics" jsonb DEFAULT '[]' NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "completed_at" timestamptz);
CREATE TABLE IF NOT EXISTS "comment_lens_comment" ("id" text PRIMARY KEY NOT NULL, "scan_id" text NOT NULL REFERENCES "comment_lens_scan"("id"), "path" text NOT NULL, "language" text NOT NULL, "kind" text NOT NULL, "body_text" text NOT NULL, "raw_text" text NOT NULL, "context" text, "payload" jsonb NOT NULL, "priority_score" integer, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "comment_lens_review" ("comment_id" text PRIMARY KEY NOT NULL REFERENCES "comment_lens_comment"("id"), "status" text NOT NULL, "note" text, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "comment_lens_chunk" ("scan_id" text NOT NULL REFERENCES "comment_lens_scan"("id"), "chunk_id" text NOT NULL, "payload" jsonb NOT NULL, "received_at" timestamptz DEFAULT now() NOT NULL, PRIMARY KEY ("scan_id","chunk_id"));
CREATE TABLE IF NOT EXISTS "comment_lens_assessment" ("comment_id" text PRIMARY KEY NOT NULL REFERENCES "comment_lens_comment"("id"), "model" text NOT NULL, "payload" jsonb NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
